// 真实委任只扩原批准的签字来源；唯一Task、钱粮、民心及原Office仍由原领域完整核验。
#include "political_governance_agency_world.hpp"
#include "world_bundle.hpp"
#include "occupation_fiscal_integration.hpp"
#include "political_takeover_execution_world.hpp"
#include "resident/domains/military/military_roster_history.hpp"
#include <limits>
namespace hanmo::resident {namespace {
// 旧签字时刻不扩张；只读取同半日稍后发生的真实军事死因以保先签后死的旧许可。
FamilyDeathOriginRead life(const WorldBundle& w,const DynamicStepInput* phase){return [&w,phase](const StableId& actor)->Outcome<std::optional<FamilyDeathOrigin>>{auto death=phase?query_military_actor_death(w.common,w.military,actor,*phase):query_military_actor_death(w.common,w.military,actor);if(!death.ok)return {false,{},death.error};if(!death.value)return {true,std::nullopt,{}};const auto& d=*death.value;return {true,FamilyDeathOrigin{d.actor_id,d.casualty_fact_id,d.battle_id,d.tick},{}};};}
// 首片实际办理只出PoliticsEffects；代理发行还必须带该次原治理批准ID，不能冒原Office receipt。
bool actual(const CommitResult& r,const StableId& source,const StableId& authority){const auto* e=r.details?std::get_if<PoliticsEffects>(&r.details->data):nullptr;return r.ok&&e&&valid_political_governance_agency_effect(r.kind,*e)&&e->fact_ids==std::vector<StableId>{source}&&e->receipt_ids==(authority.empty()?std::vector<StableId>{}:std::vector<StableId>{authority});}
Status player(const WorldBundle& w,const StableId& actor,const PoliticalGovernanceAgencyCommand& command){auto v=command_common_guard(w,actor,political_governance_agency_command_kind(command));if(!v.ok)return v;return actor==w.common.state().metadata.player_actor_id?common_success():common_failure("PoliticalGovernanceAgencyPlayerCommandRequired");}
}
// 声明序与初始化同序，回调只借本持者及同World，任何phase借用均止于本次调用返回。
PoliticalGovernanceAgencyWorldAccess::PoliticalGovernanceAgencyWorldAccess(const WorldBundle& w,const DynamicStepInput* phase)
 :world_(w),military_(w.political_takeover_enabled()?std::optional<MilitaryAccess>{w.services.military_access({},phase)}:std::nullopt),occupations_(w.political_takeover_enabled()?std::optional<PoliticalSuccessionOccupationContext>{PoliticalSuccessionOccupationContext{w.political_takeover,*w.catalog->political_takeover,w.military,*w.catalog->military,*military_}}:std::nullopt),territory_{w.common,w.politics,*w.catalog->politics,occupations_?&*occupations_:nullptr,phase},rules_{w.common,*w.catalog->common,w.politics,*w.catalog->politics,w.politics_governance,*w.catalog->politics_governance,w.organization,*w.catalog->organization,w.local_economy,w.services,*w.catalog->political_governance_agencies,*w.political_governance_agencies,life(w,phase),[this](const PoliticalGovernanceAgencyPolicy& p,Integer tick,const StableId& fact){return validate_political_governance_agency_seat(territory_,p,tick,fact);},[&w](Integer tick,const StableId& fact){return read_political_governance_agency_player_before_fact(w.common,w.family,w.family_legacy_enabled()?&w.family_legacy:nullptr,tick,fact);},phase,w.catalog->director?w.catalog->director->governance_agency_intents.get():nullptr,nullptr},read_(rules_),context_{rules_,*w.catalog->public_relief,actual}{}
Outcome<std::unique_ptr<PoliticalGovernanceAgencyWorldAccess>> PoliticalGovernanceAgencyWorldAccess::create(const WorldBundle& w,const DynamicStepInput* phase){
 if(bool(w.catalog->political_governance_agencies)!=w.political_governance_agencies.has_value())return {false,{},common_failure("PoliticalGovernanceAgencyProfileMismatch").error};
 if(!w.catalog->political_governance_agencies)return {true,nullptr,{}};
 const auto* intents=w.catalog->director?w.catalog->director->governance_agency_intents.get():nullptr;if((w.catalog->political_governance_agencies->version==2)!=bool(intents)||w.political_governance_agencies->version!=w.catalog->political_governance_agencies->version)return {false,{},common_failure("GovernanceAgencyIntentVersionPairRequired").error};
 if(!w.politics_enabled()||!w.politics_governance_enabled()||!w.catalog->politics_governance||!w.catalog->politics_governance->enabled||!w.governance_tasks_enabled()||!w.governance_tasks_seed_complete||!w.public_relief_enabled()||!w.catalog->public_relief||!w.catalog->organization||!w.catalog->organization->enabled||!w.family_life_enabled()||!w.catalog->common)return {false,{},common_failure("PoliticalGovernanceAgencyDependenciesRequired").error};
 if(phase&&(w.common.tick()<0||w.common.tick()==std::numeric_limits<Integer>::max()||phase->from_tick!=w.common.tick()||phase->to_tick!=w.common.tick()+1))return {false,{},common_failure("PoliticalGovernanceAgencyPhaseMismatch").error};
 return {true,std::unique_ptr<PoliticalGovernanceAgencyWorldAccess>{new PoliticalGovernanceAgencyWorldAccess(w,phase)},{}};
}
// BundleServices仅持World原引用，值DTO返回后销毁短栈持者，不跨候选保存rules引用。
Outcome<PoliticalGovernanceAgencySource> BundleServices::agency_for_commission(const StableId& offer,const StableId& actor)const{auto a=PoliticalGovernanceAgencyWorldAccess::create(world_);if(!a.ok)return {false,{},a.error};return a.value?a.value->read().agency_for_commission(offer,actor):Outcome<PoliticalGovernanceAgencySource>{false,{},common_failure("PoliticalGovernanceAgencyProfileRequired").error};}
Outcome<PoliticalGovernanceAgencySource> BundleServices::agency_before_issue(const StableId& offer,const StableId& fact,Integer tick)const{auto a=PoliticalGovernanceAgencyWorldAccess::create(world_);if(!a.ok)return {false,{},a.error};return a.value?a.value->read().agency_before_issue(offer,fact,tick):Outcome<PoliticalGovernanceAgencySource>{false,{},common_failure("PoliticalGovernanceAgencyProfileRequired").error};}
Outcome<PoliticalGovernanceAgencySource> BundleServices::agency_for_issued_authority(const StableId& fact)const{auto a=PoliticalGovernanceAgencyWorldAccess::create(world_);if(!a.ok)return {false,{},a.error};return a.value?a.value->read().agency_for_issued_authority(fact):Outcome<PoliticalGovernanceAgencySource>{false,{},common_failure("PoliticalGovernanceAgencyProfileRequired").error};}
Status validate_political_governance_agency_world(const WorldBundle& w){auto v=validate_political_governance_agency_layout(w.common,w.catalog->identity.module_versions,w.political_governance_agencies?&*w.political_governance_agencies:nullptr);if(!v.ok)return v;auto a=PoliticalGovernanceAgencyWorldAccess::create(w);if(!a.ok)return {false,{},a.error};return a.value?validate_political_governance_agencies(a.value->context()):common_success();}
// 只在显式新域后移这两整门；原Task结构/预约/实物早验保留，末位再核治理Task与原钱粮来源。
Status validate_agency_governance_dependencies_world(const WorldBundle& w){
 if(!w.catalog->political_governance_agencies)return common_success();auto a=PoliticalGovernanceAgencyWorldAccess::create(w);if(!a.ok)return {false,{},a.error};if(!a.value)return common_failure("PoliticalGovernanceAgencyProfileRequired");
 GovernanceTaskRead tasks(w.common,w.tasks,w.governance_tasks);PublicReliefRead relief(w.common,w.public_relief);std::unique_ptr<OccupationFiscalSettlementWorldAccess> civil;if(w.occupation_fiscal_enabled()){auto c=OccupationFiscalSettlementWorldAccess::create(w);if(!c.ok)return {false,{},c.error};civil=std::move(c.value);}
 auto v=validate_governance_tasks(w.common,w.tasks,w.governance_tasks);if(!v.ok)return v;
 v=validate_political_governance(w.common,*w.catalog->common,w.politics,w.politics_governance,*w.catalog->politics_governance,w.organization,*w.catalog->organization,w.services,tasks,relief,w.political_fiscal_enabled()?&w.political_fiscal:nullptr,w.fiscal_settlement_enabled()?&w.fiscal_settlement:nullptr,civil.get(),&a.value->read());if(!v.ok)return v;
 v=validate_public_relief_catalog_links(w.common,w.local_economy,*w.catalog->public_relief,*w.catalog->politics,*w.catalog->politics_governance);if(!v.ok)return v;
 auto takeover=PoliticalTakeoverExecutionWorldAccess::create(w);if(!takeover.ok)return {false,{},takeover.error};PoliticsGovernanceAccess authority(w.common,w.politics,w.politics_governance,*w.catalog->politics_governance,w.organization,*w.catalog->organization,w.services,&a.value->read());return validate_public_relief(w.common,w.local_economy,*w.catalog->public_relief,w.public_relief,tasks,authority,takeover.value->economy(),takeover.value->economy()?&w.economic_takeover_execution:nullptr);
}
Outcome<PoliticalGovernanceAgencyQuote> prepare_political_governance_agency_world(const WorldBundle& w,const StableId& actor,const PoliticalGovernanceAgencyCommand& c){auto v=player(w,actor,c);if(!v.ok)return {false,{},v.error};auto a=PoliticalGovernanceAgencyWorldAccess::create(w);if(!a.ok)return {false,{},a.error};return a.value?preview_political_governance_agency_business(a.value->context(),actor,c):Outcome<PoliticalGovernanceAgencyQuote>{false,{},common_failure("PoliticalGovernanceAgencyProfileRequired").error};}
Outcome<PoliticsEffects> commit_political_governance_agency_world(WorldBundle& w,const StableId& actor,const PoliticalGovernanceAgencyCommand& c,const PoliticalGovernanceAgencyQuote& q){auto v=player(w,actor,c);if(!v.ok)return {false,{},v.error};auto a=PoliticalGovernanceAgencyWorldAccess::create(w);if(!a.ok)return {false,{},a.error};if(!a.value)return {false,{},common_failure("PoliticalGovernanceAgencyProfileRequired").error};auto id=apply_political_governance_agency_business_in_candidate(w.common,w.politics_governance,*w.political_governance_agencies,a.value->context(),actor,c,q);if(!id.ok)return {false,{},id.error};std::vector<StableId> authorities;if(const auto* issued=w.political_governance_agencies->issues.find(id.value))authorities.push_back(issued->authority_fact_id);return {true,{{},{id.value},std::move(authorities)},{}};}
Outcome<BoundaryValue> query_political_governance_agency_world(const WorldBundle& w,const StableId& place,Integer cursor){auto a=PoliticalGovernanceAgencyWorldAccess::create(w);if(!a.ok)return {false,{},a.error};return a.value?query_political_governance_agencies(a.value->context(),place,cursor):Outcome<BoundaryValue>{false,{},common_failure("PoliticalGovernanceAgencyProfileRequired").error};}
Status bind_political_governance_agency_result_world(WorldBundle& w,const StableId& source,const StableId& actor,Integer request,const CommitResult& result){if(!w.catalog->political_governance_agencies||!w.political_governance_agencies||source.empty()||!is_political_governance_agency_command(result.kind))return common_failure("PoliticalGovernanceAgencyNewSourceRequired");return bind_political_governance_agency_player_result(w.common,*w.political_governance_agencies,source,actor,request,result,actual);}
}
